-- Starter estimate templates (the chain-link fence, the tiles, porta cabin and GCC starters, and the catalogue fields of the others)
-- and the illustrative catalogue items the GCC starters (pipes, precast elements, civil basics) price their materials from.
-- Run AFTER supabase/migrations/0131_estimator.sql and 0213_estimate_template_catalogue.sql; the catalogue items need 0098 (products).
-- Idempotent: a template is added if the workspace has none of that name; a workspace's own
-- editable template is never changed; the LOCKED starters are refreshed to the current ones. A catalogue item is added only when the
-- workspace has no product with that SKU, so an item edited or repriced from a rate sheet is never overwritten.
-- GENERATED by scripts/gen-estimate-seeds.ts from src/lib/estimator/starterTemplates.ts; do not
-- edit by hand, change that file and regenerate.
--
-- WHO GETS IT: every DEMO tenant (is_demo = true) that has the estimator module on.
--
-- ONE OTHER WORKSPACE (for example a client that has the estimator module): either press
-- "Add the ... starter" in that workspace's Settings > Estimate templates (no SQL; it adds the catalogue items too),
-- or change the single line marked TARGET below to
--     select id from tenants where slug = '<the workspace slug>' and coalesce((features->>'estimator')::boolean, false)
-- and run it. A live client is never targeted by this file as shipped.

do $seed$
declare
  t uuid;
  seq int;
  item record;
begin
  if not exists (select 1 from information_schema.columns where table_name = 'estimate_templates' and column_name = 'locked') then
    raise exception 'Run supabase/migrations/0213_estimate_template_catalogue.sql first (estimate_templates.locked is missing).';
  end if;
  if to_regclass('public.estimate_templates') is null then
    raise exception 'Run supabase/migrations/0131_estimator.sql first.';
  end if;

  for t in -- TARGET
    select id from tenants where is_demo = true and coalesce((features->>'estimator')::boolean, false)
  loop

    if not exists (select 1 from estimate_templates where tenant_id = t and lower(name) = lower('Precast villa (illustrative)')) then
      insert into estimate_templates (tenant_id, name, description, trade, geometry, version, is_active, quote_granularity, inputs, rates, rules, keywords, icon, locked, customer_visible)
      values (
        t, 'Precast villa (illustrative)', 'ILLUSTRATIVE starter for a precast villa with a boundary wall, built from an exact piece model (wall panels, planks, beams, columns, stairs, boundary panels). All rates, ratios and rules are placeholders to demonstrate the estimator, not any company''s real prices or method. Duplicate it and replace them with your own.', 'precast', 'precast_villa', 1, true, 'group',
        $inputs$[{"key":"floors","label":"Number of floors","type":"number","default":2,"min":1,"max":4,"unit":"floors","section":"Building"},{"key":"built_up_area_m2","label":"Built-up area per floor","type":"number","default":150,"min":20,"max":2000,"unit":"m²","help":"Area of ONE floor; every floor is the same shape.","section":"Building"},{"key":"wall_perimeter_m","label":"External wall perimeter (one floor)","type":"number","default":50,"min":10,"max":500,"unit":"m","help":"With the area, this fixes the length and depth of the building.","section":"Building"},{"key":"wall_height_m","label":"Floor-to-floor wall height","type":"number","default":3,"min":2.4,"max":6,"unit":"m","section":"Building"},{"key":"ext_wall_thickness_m","label":"External wall thickness","type":"number","default":0.2,"min":0.1,"max":0.5,"unit":"m","section":"Building"},{"key":"finish_level","label":"External finish","type":"select","default":"standard","options":[{"key":"basic","label":"Basic","value":1},{"key":"standard","label":"Standard","value":1.08},{"key":"premium","label":"Premium","value":1.18}],"quote_alternatives":true,"help":"Standard adds 8% and Premium 18% to the concrete price of the faces that show.","section":"Building"},{"key":"include_stairs","label":"Include precast stairs","type":"boolean","default":true,"section":"Stairs"},{"key":"stair_flights","label":"Stair flights","type":"number","default":2,"min":0,"max":10,"unit":"flights","section":"Stairs"},{"key":"boundary_wall_length_m","label":"Boundary wall length","type":"number","default":60,"min":0,"max":2000,"unit":"m","section":"Boundary wall"},{"key":"boundary_wall_height_m","label":"Boundary wall height","type":"number","default":2.4,"min":1,"max":4,"unit":"m","section":"Boundary wall"},{"key":"wall_colour","label":"Wall colour","type":"select","default":"grey","options":[{"key":"grey","label":"Precast grey","value":1,"visual":"concrete_precast"},{"key":"smooth","label":"Smooth concrete","value":2,"visual":"concrete_smooth"},{"key":"sand","label":"Sand","value":3,"visual":"#d9ccb4"},{"key":"white","label":"White","value":4,"visual":"#ecebe7"}],"paints":"wall","section":"Appearance"},{"key":"slab_colour","label":"Roof and slab colour","type":"select","default":"grey","options":[{"key":"grey","label":"Precast grey","value":1,"visual":"concrete_precast"},{"key":"smooth","label":"Smooth concrete","value":2,"visual":"concrete_smooth"},{"key":"sand","label":"Sand","value":3,"visual":"#d9ccb4"},{"key":"white","label":"White","value":4,"visual":"#ecebe7"}],"paints":"slab","section":"Appearance"}]$inputs$::jsonb,
        $rates$[{"key":"concrete_density_t_m3","label":"Concrete density","unit":"t/m³","value":2.4},{"key":"rebar_kg_per_m3","label":"Reinforcement per m³ of concrete","unit":"kg/m³","value":100},{"key":"insulated_area_share","label":"Share of external wall face that is insulated","unit":"fraction","value":0.9},{"key":"insert_spacing_m3","label":"Concrete served by one lifting insert","unit":"m³","value":1.2},{"key":"wastage_pct","label":"Wastage on concrete, steel and boards","unit":"%","value":0},{"key":"concrete_cost_m3","label":"Precast concrete, supplied and cast","unit":"per m³","value":330,"low":297,"high":412.5},{"key":"rebar_cost_kg","label":"Reinforcement steel, cut and bent","unit":"per kg","value":3.2,"low":2.72,"high":4.32},{"key":"insulation_cost_m2","label":"Insulation board","unit":"per m²","value":38,"low":34.2,"high":43.7},{"key":"fixing_cost_nr","label":"Lifting insert and fixings","unit":"per nr","value":65,"low":58.5,"high":74.75},{"key":"mould_cost_m3","label":"Mould usage","unit":"per m³","value":90},{"key":"labour_hours_per_m3","label":"Production labour hours per m³","unit":"h/m³","value":3.5,"low":3.18,"high":4.375},{"key":"labour_rate_hr","label":"Production labour rate","unit":"per h","value":18,"low":16.2,"high":21.6},{"key":"transport_load_capacity_t","label":"Transport capacity per load","unit":"t/load","value":25},{"key":"transport_cost_load","label":"Transport cost per load","unit":"per load","value":1800,"low":1620,"high":2340},{"key":"erection_cost_m3","label":"Erection","unit":"per m³","value":120,"low":108,"high":150},{"key":"overhead_factor","label":"Factory and yard overhead (share of production cost)","unit":"fraction","value":0.12},{"key":"cap_cast_m3_per_day","label":"Casting capacity","unit":"m³/day","value":18},{"key":"cap_trucks_loads_per_day","label":"Truck loads leaving the factory","unit":"loads/day","value":4},{"key":"cap_crane_m3_per_day","label":"Crane erection capacity","unit":"m³/day","value":24},{"key":"transport_start_day","label":"Transport starts on day","unit":"day","value":5},{"key":"erection_start_day","label":"Erection starts on day","unit":"day","value":6}]$rates$::jsonb,
        $rules$[{"code":"iw","group":"Structure (floors, beams, inner walls)","description":"Internal wall panels","uom":"m3","qty":"vol_IW","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"}},{"code":"sl","group":"Structure (floors, beams, inner walls)","description":"Hollow-core floor and roof planks","uom":"m3","qty":"vol_SL","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"slab"},{"code":"fr","group":"Structure (floors, beams, inner walls)","description":"Beams and columns","uom":"m3","qty":"vol_FR","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"beam"},{"code":"ew","group":"External walls and parapet","description":"External wall panels (insulated)","uom":"m3","qty":"vol_EW","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"wall_panel"},{"code":"pr","group":"External walls and parapet","description":"Parapet panels","uom":"m3","qty":"vol_PR","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"parapet_panel"},{"code":"fin","group":"External walls and parapet","description":"External finish premium (extra concrete cost on the faces that show)","uom":"m3","qty":"(vol_EW + vol_PR + vol_BW) * (finish_level - 1)","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"}},{"code":"st","group":"Stairs","description":"Stair flights","uom":"m3","qty":"vol_ST","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"stair"},{"code":"bw","group":"Boundary wall","description":"Boundary wall panels","uom":"m3","qty":"vol_BW","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"concrete_cost_m3"},"element_type":"boundary_panel"},{"code":"rbr","group":"Production","description":"Reinforcement steel","uom":"kg","qty":"vol_total * rebar_kg_per_m3","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"rebar_cost_kg"}},{"code":"mld","group":"Production","description":"Mould usage","uom":"m3","qty":"vol_total","component":"moulds","cost":{"kind":"rate","rate":"mould_cost_m3"}},{"code":"lab","group":"Production","description":"Production labour","uom":"h","qty":"vol_total * labour_hours_per_m3","component":"labour","cost":{"kind":"rate","rate":"labour_rate_hr"}},{"code":"ins","group":"Insulation and fixings","description":"Wall insulation board","uom":"m2","qty":"area_EW * insulated_area_share","waste_pct":"wastage_pct","component":"materials","cost":{"kind":"rate","rate":"insulation_cost_m2"}},{"code":"fix","group":"Insulation and fixings","description":"Lifting inserts and fixings","uom":"nr","qty":"ceil(vol_total / insert_spacing_m3)","component":"materials","cost":{"kind":"rate","rate":"fixing_cost_nr"}},{"code":"trl","group":"Delivery and erection","description":"Transport to site (loads by weight)","uom":"load","qty":"ceil(weight_total / transport_load_capacity_t)","component":"transport","cost":{"kind":"rate","rate":"transport_cost_load"}},{"code":"ere","group":"Delivery and erection","description":"Erection","uom":"m3","qty":"vol_total","component":"erection","cost":{"kind":"rate","rate":"erection_cost_m3"}},{"code":"ovh","group":"Overhead","description":"Factory and yard overhead","uom":"cost","qty":"sub_structure_floors_beams_inner_walls + sub_external_walls_and_parapet + sub_stairs + sub_boundary_wall + sub_production","component":"overhead","cost":{"kind":"rate","rate":"overhead_factor"}}]$rules$::jsonb,
        array['precast', 'villa', 'house', 'building', 'prefab', 'wall panels', 'hollow core', 'boundary wall', 'residential', 'floors']::text[], 'building', false, false
      );
    else
      -- Already there: the catalogue fields are filled only where empty. A LOCKED starter is
      -- product-owned, so its inputs, rates and rules are refreshed to the current ones (the
      -- version goes up when they changed); an editable template of the workspace is left alone.
      update estimate_templates set
        keywords = coalesce(keywords, array['precast', 'villa', 'house', 'building', 'prefab', 'wall panels', 'hollow core', 'boundary wall', 'residential', 'floors']::text[]),
        icon = coalesce(icon, 'building')
      where tenant_id = t and lower(name) = lower('Precast villa (illustrative)');
      
    end if;

    if not exists (select 1 from estimate_templates where tenant_id = t and lower(name) = lower('Chain-link fence')) then
      insert into estimate_templates (tenant_id, name, description, trade, geometry, version, is_active, quote_granularity, inputs, rates, rules, keywords, icon, locked, customer_visible)
      values (
        t, 'Chain-link fence', 'Perimeter or straight-run chain-link fence: posts, fabric, gates and fittings, priced from your catalogue.', 'fencing', 'chainlink_fence', 1, true, 'line',
        $inputs$[{"key":"total_length_m","label":"Fence length","type":"number","default":500,"min":1,"max":5000,"unit":"m","help":"The whole length of fence, gates included.","section":"The fence"},{"key":"closed_perimeter","label":"Goes all the way round","type":"boolean","default":true,"help":"Yes for a closed boundary (four corners). No for a single straight run (two end posts).","section":"The fence"},{"key":"post_spacing_m","label":"What is being protected","type":"select","default":"general","options":[{"key":"general","label":"General yard and storage","value":3,"attrs":{"pipe_class":"Schedule 40"}},{"key":"vehicle","label":"Vehicle and equipment compound","value":2.5,"attrs":{"pipe_class":"SS20"}},{"key":"bonded","label":"Bonded or high-value storage","value":2,"attrs":{"pipe_class":"SS40"}}],"help":"Sets how far apart the posts are and which pipe class they use.","section":"The fence"},{"key":"fabric_height_m","label":"Fence height","type":"number","default":2,"min":1,"max":6,"unit":"m","section":"The fence"},{"key":"mesh","label":"Mesh","type":"select","default":"standard","options":[{"key":"standard","label":"Standard 50x50, 2.5 mm","value":1,"attrs":{"mesh_spec":"Chain-link 50x50 . 2.5mm"}},{"key":"high_security","label":"High security 25x25, 3.0 mm","value":2,"attrs":{"mesh_spec":"Chain-link 25x25 . 3.0mm (high security)"}},{"key":"mini_mesh","label":"Mini-mesh 16x16, 4.9 mm","value":3,"attrs":{"mesh_spec":"Chain-link 16x16 . 4.9mm (mini-mesh)"}}],"section":"The fence"},{"key":"coating","label":"Coating","type":"select","default":"pvc","options":[{"key":"pvc","label":"PVC coated","value":1,"attrs":{"coating":"PVC coated"}}],"section":"The fence"},{"key":"straining_spacing_m","label":"Distance between straining posts","type":"number","default":100,"min":10,"max":500,"unit":"m","section":"The fence"},{"key":"gates_single_n","label":"Single gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_single_w","label":"Single gate width","type":"number","default":1.2,"min":0.6,"max":3,"unit":"m","section":"Gates"},{"key":"gates_double_n","label":"Double gates","type":"number","default":2,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_double_w","label":"Double gate width","type":"number","default":5,"min":2,"max":12,"unit":"m","section":"Gates"},{"key":"gates_sliding_n","label":"Sliding gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_sliding_w","label":"Sliding gate width","type":"number","default":6,"min":2,"max":20,"unit":"m","section":"Gates"},{"key":"truss_rods","label":"Truss rods at corners and straining posts","type":"boolean","default":true,"section":"Fittings"},{"key":"tension_wire","label":"Tension wire (3 rows)","type":"boolean","default":true,"section":"Fittings"},{"key":"tie_wire","label":"Tie wire","type":"boolean","default":true,"section":"Fittings"},{"key":"barbed_wire","label":"Barbed wire on top (3 strands)","type":"boolean","default":false,"section":"Fittings"},{"key":"mesh_colour","label":"Mesh colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"mesh","section":"Appearance"},{"key":"post_colour","label":"Post colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"posts","section":"Appearance"}]$inputs$::jsonb,
        $rates$[]$rates$::jsonb,
        $rules$[{"code":"line_posts","group":"Posts","description":"Line posts","uom":"pcs","qty":"n_LP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"line_post"},"from":["post_spacing_m","coating"]}}},{"code":"straining_posts","group":"Posts","description":"Straining posts","uom":"pcs","qty":"n_SP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"straining_post"},"from":["post_spacing_m","coating"]}}},{"code":"corner_posts","group":"Posts","description":"Corner posts","uom":"pcs","qty":"n_CP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"corner_post"},"from":["post_spacing_m","coating"]}}},{"code":"terminal_posts","group":"Posts","description":"Terminal posts","uom":"pcs","qty":"n_TP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"terminal_post"},"from":["post_spacing_m","coating"]}}},{"code":"gate_posts","group":"Posts","description":"Gate posts","uom":"pcs","qty":"n_GP","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"gate_post"},"from":["post_spacing_m","coating"]}}},{"code":"fabric","group":"Chain-link fabric","description":"Chain-link fabric","uom":"m2","qty":"area_FB","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"fabric"},"from":["mesh","coating"]}}},{"code":"tension_bands","group":"Fittings and hardware","description":"Tension bands","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * max(3, ceil(fabric_height_m / 0.3))","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tension_band"},"from":["coating"]}}},{"code":"brace_bands","group":"Fittings and hardware","description":"Brace bands","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * 2","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"brace_band"},"from":["coating"]}}},{"code":"rail_ends","group":"Fittings and hardware","description":"Rail ends","uom":"pcs","qty":"(n_CP + n_TP + n_SP + n_GP) * 2","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"rail_end"},"from":["coating"]}}},{"code":"carriage_bolts","group":"Fittings and hardware","description":"Carriage bolt sets","uom":"sets","qty":"qty_tension_bands + qty_brace_bands","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"carriage_bolt_set"},"from":["coating"]}}},{"code":"truss_sets","group":"Fittings and hardware","description":"Truss rod sets","uom":"sets","qty":"truss_rods * (n_CP + n_SP)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"truss_rod_set"},"from":["coating"]}}},{"code":"tension_wire_m","group":"Wire","description":"Tension wire","uom":"m","qty":"tension_wire * round(total_length_m * 3)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tension_wire"},"from":["coating"]}}},{"code":"tie_wire_kg","group":"Wire","description":"Tie wire","uom":"kg","qty":"tie_wire * round(total_length_m * 0.0186, 1)","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"tie_wire"},"from":["coating"]}}},{"code":"barbed_wire_m","group":"Wire","description":"Barbed wire","uom":"m","qty":"barbed_wire * total_length_m * 3","component":"materials","cost":{"kind":"product","match":{"attrs":{"fence_kind":"barbed_wire"},"from":["coating"]}}}]$rules$::jsonb,
        array['fence', 'fencing', 'chain link', 'chainlink', 'perimeter', 'boundary', 'compound', 'yard', 'gate', 'posts', 'mesh', 'security fence', 'barbed wire']::text[], 'fence', true, false
      );
    else
      -- Already there: the catalogue fields are filled only where empty. A LOCKED starter is
      -- product-owned, so its inputs, rates and rules are refreshed to the current ones (the
      -- version goes up when they changed); an editable template of the workspace is left alone.
      update estimate_templates set
        keywords = coalesce(keywords, array['fence', 'fencing', 'chain link', 'chainlink', 'perimeter', 'boundary', 'compound', 'yard', 'gate', 'posts', 'mesh', 'security fence', 'barbed wire']::text[]),
        icon = coalesce(icon, 'fence')
      where tenant_id = t and lower(name) = lower('Chain-link fence');
      update estimate_templates set
        inputs = $inputs$[{"key":"total_length_m","label":"Fence length","type":"number","default":500,"min":1,"max":5000,"unit":"m","help":"The whole length of fence, gates included.","section":"The fence"},{"key":"closed_perimeter","label":"Goes all the way round","type":"boolean","default":true,"help":"Yes for a closed boundary (four corners). No for a single straight run (two end posts).","section":"The fence"},{"key":"post_spacing_m","label":"What is being protected","type":"select","default":"general","options":[{"key":"general","label":"General yard and storage","value":3,"attrs":{"pipe_class":"Schedule 40"}},{"key":"vehicle","label":"Vehicle and equipment compound","value":2.5,"attrs":{"pipe_class":"SS20"}},{"key":"bonded","label":"Bonded or high-value storage","value":2,"attrs":{"pipe_class":"SS40"}}],"help":"Sets how far apart the posts are and which pipe class they use.","section":"The fence"},{"key":"fabric_height_m","label":"Fence height","type":"number","default":2,"min":1,"max":6,"unit":"m","section":"The fence"},{"key":"mesh","label":"Mesh","type":"select","default":"standard","options":[{"key":"standard","label":"Standard 50x50, 2.5 mm","value":1,"attrs":{"mesh_spec":"Chain-link 50x50 . 2.5mm"}},{"key":"high_security","label":"High security 25x25, 3.0 mm","value":2,"attrs":{"mesh_spec":"Chain-link 25x25 . 3.0mm (high security)"}},{"key":"mini_mesh","label":"Mini-mesh 16x16, 4.9 mm","value":3,"attrs":{"mesh_spec":"Chain-link 16x16 . 4.9mm (mini-mesh)"}}],"section":"The fence"},{"key":"coating","label":"Coating","type":"select","default":"pvc","options":[{"key":"pvc","label":"PVC coated","value":1,"attrs":{"coating":"PVC coated"}}],"section":"The fence"},{"key":"straining_spacing_m","label":"Distance between straining posts","type":"number","default":100,"min":10,"max":500,"unit":"m","section":"The fence"},{"key":"gates_single_n","label":"Single gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_single_w","label":"Single gate width","type":"number","default":1.2,"min":0.6,"max":3,"unit":"m","section":"Gates"},{"key":"gates_double_n","label":"Double gates","type":"number","default":2,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_double_w","label":"Double gate width","type":"number","default":5,"min":2,"max":12,"unit":"m","section":"Gates"},{"key":"gates_sliding_n","label":"Sliding gates","type":"number","default":0,"min":0,"max":20,"unit":"gates","section":"Gates"},{"key":"gates_sliding_w","label":"Sliding gate width","type":"number","default":6,"min":2,"max":20,"unit":"m","section":"Gates"},{"key":"truss_rods","label":"Truss rods at corners and straining posts","type":"boolean","default":true,"section":"Fittings"},{"key":"tension_wire","label":"Tension wire (3 rows)","type":"boolean","default":true,"section":"Fittings"},{"key":"tie_wire","label":"Tie wire","type":"boolean","default":true,"section":"Fittings"},{"key":"barbed_wire","label":"Barbed wire on top (3 strands)","type":"boolean","default":false,"section":"Fittings"},{"key":"mesh_colour","label":"Mesh colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"mesh","section":"Appearance"},{"key":"post_colour","label":"Post colour","type":"select","default":"green","options":[{"key":"galvanised","label":"Galvanised","value":1,"visual":"galvanised"},{"key":"green","label":"Green PVC","value":2,"visual":"pvc_green"},{"key":"black","label":"Black PVC","value":3,"visual":"pvc_black"},{"key":"blue","label":"Blue PVC","value":4,"visual":"pvc_blue"}],"paints":"posts","section":"Appearance"}]$inputs$::jsonb,
